import React from 'react';
import { ArrayField } from '@formily/core';
import { useField, observer, useFieldSchema, RecursionField, ReactFC } from '@formily/react';
import cls from 'classnames';
import { Card as ArcoCard, Empty as ArcoEmpty } from '@arco-design/web-react';
import { ISchema } from '@formily/json-schema';
import { usePrefixCls } from '../__builtins__';
import { ArrayBase, ArrayBaseMixins } from '../ArrayBase';

type ComposedArrayCards = React.FC<React.PropsWithChildren<HTMLDivElement>> & ArrayBaseMixins;

const isAdditionComponent = (schema: ISchema) => schema['x-component']?.indexOf('Addition') > -1;

const isIndexComponent = (schema: ISchema) => schema['x-component']?.indexOf?.('Index') > -1;

const isRemoveComponent = (schema: ISchema) => schema['x-component']?.indexOf?.('Remove') > -1;

const isCopyComponent = (schema: ISchema) => schema['x-component']?.indexOf?.('Copy') > -1;

const isMoveUpComponent = (schema: ISchema) => schema['x-component']?.indexOf?.('MoveUp') > -1;

const isMoveDownComponent = (schema: ISchema) => schema['x-component']?.indexOf?.('MoveDown') > -1;

const isOperationComponent = (schema: ISchema) =>
  isAdditionComponent(schema) ||
  isRemoveComponent(schema) ||
  isCopyComponent(schema) ||
  isMoveDownComponent(schema) ||
  isMoveUpComponent(schema);

export const ArrayCards: ComposedArrayCards = observer(props => {
  const field = useField<ArrayField>();
  const schema = useFieldSchema();
  const dataSource = Array.isArray(field.value) ? field.value : [];
  const prefixCls = usePrefixCls('formily-array-cards');

  if (!schema) {
    throw new Error('can not found schema object');
  }

  const renderItems = () =>
    dataSource?.map((item, index) => {
      const items = Array.isArray(schema.items) ? schema.items[index] || schema.items[0] : schema.items;
      const title = (
        <span>
          <RecursionField
            schema={items!}
            name={index}
            filterProperties={schema => {
              if (!isIndexComponent(schema)) {
                return false;
              }
              return true;
            }}
            onlyRenderProperties
          />
          {props.title || field.title}
        </span>
      );
      const extra = (
        <span>
          <RecursionField
            schema={items!}
            name={index}
            filterProperties={schema => {
              if (!isOperationComponent(schema)) {
                return false;
              }
              return true;
            }}
            onlyRenderProperties
          />
          {/* TODO */}
          {/* @ts-ignore */}
          {props.extra}
        </span>
      );
      const content = (
        <RecursionField
          schema={items!}
          name={index}
          filterProperties={schema => {
            if (isIndexComponent(schema)) {
              return false;
            }
            if (isOperationComponent(schema)) {
              return false;
            }
            return true;
          }}
        />
      );
      return (
        <ArrayBase.Item key={index} index={index} record={() => field.value?.[index]}>
          {/* TODO */}
          {/* @ts-ignore */}
          <ArcoCard
            {...props}
            onChange={() => { }}
            className={cls(`${prefixCls}-item`, props.className)}
            title={title}
            extra={extra}
          >
            {content}
          </ArcoCard>
        </ArrayBase.Item>
      );
    });

  const renderAddition = () =>
    schema.reduceProperties((addition, schema, key) => {
      if (isAdditionComponent(schema)) {
        return <RecursionField schema={schema} name={key} />;
      }
      return addition;
    }, null);

  const renderEmpty = () => {
    if (dataSource?.length) {
      return;
    }
    return (
      // TODO
      // @ts-ignore
      <ArcoCard
        {...props}
        onChange={() => { }}
        className={cls(`${prefixCls}-item`, props.className)}
        title={props.title || field.title}
      >
        <ArcoEmpty />
      </ArcoCard>
    );
  };
  return (
    <ArrayBase mode="schema">
      {renderEmpty()}
      {renderItems()}
      {renderAddition()}
    </ArrayBase>
  );
});

ArrayCards.displayName = 'ArrayCards';

ArrayBase.mixin(ArrayCards);

export default ArrayCards;
